\set ON_ERROR_STOP on
begin;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);

insert into public.properties(id,owner_id,name,slug,description,city,state,bedrooms,bathrooms,max_guests,property_type,timezone,source,product_participation)
values('94000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','FSUX6 controlled property','fsux6-controlled-property','Controlled local fixture','Austin','TX',2,2,6,'home','America/Chicago','manual',array['furnishing_project']);
insert into public.furnishing_retailers(id,name,website_url,status)values('94000000-0000-4000-8000-000000000002','FSUX6 Controlled Retailer','https://example.invalid','active');
insert into public.furnishing_products(id,workspace_id,name,product_type,category,status,scope,created_by,revision)values('94000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','FSUX6 controlled sofa','catalog_item','Furniture','approved','workspace','10000000-0000-4000-8000-000000000001',1);
insert into public.furnishing_product_versions(id,product_id,workspace_id,version,lifecycle_status,product_snapshot,correlation_id,idempotency_key,created_by,approved_by,approved_at)values('94000000-0000-4000-8000-000000000004','94000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001',1,'approved','{"variant":"oatmeal"}','94000000-0000-4000-8000-000000000014','fsux6-product-version','10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',now());
insert into public.furnishing_product_offers(id,product_id,retailer_id,sku,product_url,listed_price_minor,shipping_price_minor,currency,availability,last_verified_at,status)values('94000000-0000-4000-8000-000000000005','94000000-0000-4000-8000-000000000003','94000000-0000-4000-8000-000000000002','SOFA-001','https://example.invalid/sofa',100000,10000,'USD','in_stock',now(),'active');

do $$declare created jsonb;project_id uuid;design_version uuid;budget_id uuid;room_id uuid;customer_event uuid;approved jsonb;handoff jsonb;proc jsonb;base_id uuid;readiness_version uuid;line_id uuid;validated jsonb;submitted jsonb;reviewed jsonb;revision jsonb;before_orders bigint;before_payments bigint;before_notifications bigint;before_installations bigint;
begin
 select count(*) into before_orders from public.furnishing_procurement_orders;select count(*) into before_payments from public.commerce_payments;select count(*) into before_notifications from public.notifications;select count(*) into before_installations from public.furnishing_installation_projects;
 created:=public.fsux5_create_design_workspace('20000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001','FSUX6 approved design source',null,jsonb_build_object('design_direction','warm modern','maximum_guests',6),jsonb_build_object('currency','USD','target_minimum_minor',110000,'target_maximum_minor',140000,'inclusion_basis','products_delivery'),'fsux6-design-create','94000000-0000-4000-8000-000000000015');
 project_id:=(created->>'project_id')::uuid;design_version:=(created->>'design_version_id')::uuid;budget_id:=(created->>'budget_id')::uuid;
 insert into public.furnishing_rooms(project_id,design_version_id,room_type,name,sort_order,status)values(project_id,design_version,'living_room','Living room',0,'planning')returning id into room_id;
 insert into public.furnishing_product_selections(furnishing_plan_id,room_id,design_version_id,product_id,product_version_id,selected_offer_id,resolved_quantity,estimated_unit_price_minor,estimated_total_minor,currency,price_observed_at,selection_source,selection_status,required,priority,price_source,correlation_id)values(null,room_id,design_version,'94000000-0000-4000-8000-000000000003','94000000-0000-4000-8000-000000000004','94000000-0000-4000-8000-000000000005',1,100000,100000,'USD',now(),'manual','approved',true,'essential','approved_catalog','94000000-0000-4000-8000-000000000016');
 update public.fsux5_design_versions set state='customer_review' where id=design_version;update public.furnishing_budgets set lifecycle_status='customer_review',product_subtotal_minor=100000,delivery_minor=10000,estimated_total_minor=110000,contingency_minor=30000 where id=budget_id;
 insert into public.fsux5_review_events(project_id,design_version_id,budget_id,stage,decision,customer_identity,recording_actor,correlation_id,idempotency_key)values(project_id,design_version,budget_id,'customer','approved','10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','fsux6-customer-review','fsux6-customer-review')returning id into customer_event;
 approved:=public.fsux5_approve_design(project_id,1,customer_event,'fsux6-design-approval','fsux6-design-approval');handoff:=public.fsux5_prepare_procurement_handoff(project_id,'fsux6-handoff-command','fsux6-handoff-correlation');
 proc:=public.fsux6_create_project((handoff->>'handoff_id')::uuid,'fsux6-project-command','94000000-0000-4000-8000-000000000017');base_id:=(proc->>'project_id')::uuid;readiness_version:=(proc->>'version_id')::uuid;
 if proc->>'external_effects'<>'false' or proc->>'order_created'<>'false' or proc->>'line_count'<>'1' then raise exception 'FSUX6_CREATE_BOUNDARY_FAILED %',proc;end if;
 if public.fsux6_create_project((handoff->>'handoff_id')::uuid,'fsux6-project-command','94000000-0000-4000-8000-000000000017')->>'idempotent'<>'true' then raise exception 'FSUX6_CREATE_REPLAY_FAILED';end if;
 if not exists(select 1 from public.furnishing_procurement_lines l join public.fsux6_line_allocations a on a.line_id=l.id where l.readiness_version_id=readiness_version and l.product_version_id='94000000-0000-4000-8000-000000000004' and l.planned_quantity=a.quantity)then raise exception 'FSUX6_LINEAGE_OR_QUANTITY_FAILED';end if;
 select id into line_id from public.furnishing_procurement_lines where readiness_version_id=readiness_version;
 perform public.fsux6_update_delivery_plan(base_id,1,jsonb_build_object('address','Private controlled destination','receiving_contact','Controlled receiver','earliest','2026-09-01','latest','2026-09-15'),'fsux6-delivery-command','fsux6-delivery-correlation');
 if public.fsux6_refresh_price_evidence(base_id,line_id,2,105000,'available','manual_controlled',now(),'fsux6-price-command','fsux6-price-correlation')->>'external_effects'<>'false' then raise exception 'FSUX6_PRICE_EXTERNAL_EFFECT';end if;
 if public.fsux6_refresh_price_evidence(base_id,line_id,3,105000,'available','manual_controlled',now(),'fsux6-price-command','fsux6-price-correlation')->>'idempotent'<>'true' then raise exception 'FSUX6_PRICE_REPLAY_FAILED';end if;
 validated:=public.fsux6_validate_readiness(base_id,3,'fsux6-validation-correlation');if validated->>'result'<>'ready' then raise exception 'FSUX6_VALIDATION_FAILED %',validated;end if;
 submitted:=public.fsux6_submit_review(base_id,4,'fsux6-submit-command','fsux6-submit-correlation');if public.fsux6_submit_review(base_id,4,'fsux6-submit-command','fsux6-submit-correlation')->>'idempotent'<>'true' then raise exception 'FSUX6_SUBMIT_REPLAY_FAILED';end if;
 reviewed:=public.fsux6_review(base_id,5,'approved','Controlled readiness approval','fsux6-review-command','fsux6-review-correlation');if reviewed->>'order_created'<>'false' or reviewed->>'purchase_authorized'<>'false' then raise exception 'FSUX6_APPROVAL_EXECUTION_BOUNDARY_FAILED %',reviewed;end if;
 if public.fsux6_review(base_id,5,'approved','Controlled readiness approval','fsux6-review-command','fsux6-review-correlation')->>'idempotent'<>'true' then raise exception 'FSUX6_APPROVAL_REPLAY_FAILED';end if;
 begin update public.fsux6_readiness_snapshots set snapshot='{}' where id=(reviewed->>'snapshot_id')::uuid;raise exception 'FSUX6_SNAPSHOT_MUTABLE';exception when others then if sqlerrm not like '%PROCUREMENT_READINESS_SNAPSHOT_IMMUTABLE%' then raise;end if;end;
 begin perform public.fsux6_validate_readiness(base_id,5,'stale');raise exception 'FSUX6_STALE_ALLOWED';exception when others then if sqlerrm not like '%PROCUREMENT_VERSION_STALE%' then raise;end if;end;
 revision:=public.fsux6_create_revision(base_id,6,'fsux6-revision-command','fsux6-revision-correlation');if not exists(select 1 from public.fsux6_procurement_versions where id=(revision->>'version_id')::uuid and based_on_version_id=readiness_version and state='reconciling')then raise exception 'FSUX6_REVISION_FAILED';end if;
 if before_orders<>(select count(*)from public.furnishing_procurement_orders)or before_payments<>(select count(*)from public.commerce_payments)or before_notifications<>(select count(*)from public.notifications)or before_installations<>(select count(*)from public.furnishing_installation_projects)then raise exception 'FSUX6_EXTERNAL_EFFECT';end if;
 if exists(select 1 from public.furnishing_procurement_baselines where id=base_id and status='authorized')then raise exception 'FSUX6_READINESS_IMPLIED_PURCHASE_AUTHORIZATION';end if;
end$$;

do $$begin
 if has_function_privilege('authenticated','public.cleanup_fs008g_synthetic_project(jsonb)','EXECUTE')or has_function_privilege('anon','public.cleanup_fs008g_synthetic_project(jsonb)','EXECUTE')then raise exception 'FSUX6_CLEANUP_CLIENT_EXECUTE';end if;
 if has_function_privilege('authenticated','public.fsux6_prevent_snapshot_mutation()','EXECUTE')then raise exception 'FSUX6_INTERNAL_FUNCTION_EXPOSED';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','anon',true);
 begin perform public.fsux6_create_project('94000000-0000-4000-8000-000000000099','anonymous-denied','94000000-0000-4000-8000-000000000098');raise exception 'FSUX6_ANON_ALLOWED';exception when insufficient_privilege then null;when others then if sqlerrm not like '%permission denied%' and sqlerrm not like '%PROCUREMENT_ACCESS_DENIED%' then raise;end if;end;
end$$;
rollback;
select 'FS_UX_006_DATABASE_MATRIX_PASS' as result;
